company_id = #{companyId}


		AND start_time > #{now}


		AND start_time < #{now} AND end_time > #{now}


		AND end_time < #{now}



	AND source_id = #{sourceIdFromQuery} AND source_type = 'distributor'

mapper.select:
SELECT limit_id, company_id, limit_name, limit_type, valid_grade, rule, start_time, end_time,
	use_bound, tag_ids, brand_ids, total_item_num, valid_item_num, error_desc, created, updated, source_type, source_id
FROM promotions_limit
WHERE company_id = #{companyId}
AND start_time <= #{windowEnd}
AND end_time >= #{overlapStart}

	AND limit_id != #{excludeLimitId}

SELECT DISTINCT a.limit_id
